def dependencies(nodes):
    """Validate and build a dependency graph.

    Returns a dict mapping node id to a list of unique dependencies.
    Raises ValueError for duplicate ids, unknown dependencies, or cycles.
    """
    # Build graph with unique dependencies preserving order
    graph = {node["id"]: list(dict.fromkeys(node.get("needs", []))) for node in nodes}
    if len(graph) != len(nodes):
        raise ValueError("duplicate node")
    # Validate that all dependencies exist
    for nid, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError("unknown dependency")
    # Detect cycles using Kahn's algorithm (will be used again in order)
    _detect_cycle(graph)
    return graph

def _detect_cycle(graph):
    # Simple cycle detection: try topological sort without ordering constraints
    indegree = {n: 0 for n in graph}
    for deps in graph.values():
        for d in deps:
            indegree[d] += 1
    zero = [n for n, deg in indegree.items() if deg == 0]
    visited = 0
    while zero:
        n = zero.pop()
        visited += 1
        for m in graph[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                zero.append(m)
    if visited != len(graph):
        raise ValueError("cycle detected")

def order(graph):
    """Return a canonical topological order.

    At each step the lexicographically smallest node whose dependencies are already
    in the result list is selected. If a cycle is present, a ValueError is raised.
    """
    # Kahn's algorithm with lexicographic selection
    indegree = {n: 0 for n in graph}
    for deps in graph.values():
        for d in deps:
            indegree[d] += 1
    # start with nodes that have no incoming edges
    ready = sorted([n for n, deg in indegree.items() if deg == 0])
    result = []
    while ready:
        node = ready.pop(0)  # smallest lexicographically
        result.append(node)
        for m in graph[node]:
            indegree[m] -= 1
            if indegree[m] == 0:
                # keep list sorted
                insert_index = 0
                while insert_index < len(ready) and ready[insert_index] < m:
                    insert_index += 1
                ready.insert(insert_index, m)
    if len(result) != len(graph):
        raise ValueError("cycle detected")
    return result

